using System.ComponentModel.DataAnnotations;

namespace ViajantesTurismo.Admin.Contracts.Application;

/// <summary>Selects approved outstanding installments and a verified recipient; amounts are generated by the server.</summary>
public sealed record GeneratePaymentInstructionsDto
{
    /// <summary>Gets the expected source document-lineage version when regenerating.</summary>
    public long? ExpectedDocumentVersion
    {
        get; init;
    }
    /// <summary>Gets ExpectedVersion.</summary>
    [Range(0, long.MaxValue)]
    public required long ExpectedVersion
    {
        get; init;
    }
    /// <summary>Gets AccountId.</summary>
    public required Guid AccountId
    {
        get; init;
    }
    /// <summary>Gets ExpectedAccountVersion.</summary>
    [Range(1, long.MaxValue)]
    public required long ExpectedAccountVersion
    {
        get; init;
    }
    /// <summary>Gets QuoteId.</summary>
    public Guid? QuoteId
    {
        get; init;
    }
    /// <summary>Gets InstallmentIds.</summary>
    [Required]
    public required IReadOnlyList<Guid> InstallmentIds
    {
        get; init;
    }
    /// <inheritdoc />
    public override string ToString() => "GeneratePaymentInstructionsDto [redacted]";
}
